args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?film ?filmLabel ?director ?directorLabel ?bd WHERE {
  VALUES ?film { dbr:Sabas,_ang_barbaro dbr:Passage_to_Zarahemla }
  ?film ?dirProp ?director .
  FILTER(?dirProp IN (dbo:director, dbp:director))
  OPTIONAL { ?director dbo:birthDate ?birthDate. }
  OPTIONAL { ?director dbp:birth_date ?birthDate2. }
  OPTIONAL { ?director dbp:birthDate ?birthDate3. }
  BIND(COALESCE(?birthDate, ?birthDate2, ?birthDate3) AS ?bd)
  OPTIONAL { ?film rdfs:label ?filmLabel FILTER(lang(?filmLabel) = 'en') }
  OPTIONAL { ?director rdfs:label ?directorLabel FILTER(lang(?directorLabel) = 'en') }
  FILTER(BOUND(?bd))
}
ORDER BY DESC(?bd)
LIMIT 1

